"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
// Re-exporting a const from a "use server" file is illegal (Next throws
// "found object"), so the choices live in a plain module.
import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
import { prorateDowngradeCreditCents, remainingMonths, terminationRefundCents } from "./proration";
import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";
import { invoiceCreateData } from "./invoices";

/**
 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
 * resize-down. These complement the primary flows in `lib/actions-server.ts`
 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
 * and respects the "one in-flight job per server" invariant.
 */

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, osTemplate: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

// ---------- 1. Scheduled backups ----------

/**
 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
 * first backup on its next pass.
 */
export async function setBackupSchedule(
  serverId: string,
  enabled: boolean,
  intervalHours: number
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
    return { error: "Choose a valid backup interval." };
  }

  await db.server.update({
    where: { id: server.id },
    data: {
      autoBackup: enabled,
      backupIntervalHours: enabled ? intervalHours : null,
    },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.backup_schedule",
      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 1b. Retry a failed provision ----------

/**
 * Re-enqueue provisioning for a server that failed to build (status ERROR).
 *
 * A terminal PROVISION failure strands the server in ERROR with a red banner and
 * no way forward; this is the customer's self-service retry. It re-uses the exact
 * same job/worker machinery as the original order — the provision handler keeps
 * any vmid already persisted on the row, so a retry resumes rather than leaking a
 * second VM. Ownership-checked, guarded to ERROR only, and respects the one
 * in-flight job invariant. Moving the row to PROVISIONING immediately makes the
 * detail page show the transitional "being set up" state (and auto-refresh)
 * rather than the stale ERROR banner while the worker picks the job up.
 */
export async function retryProvision(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (server.status !== "ERROR") {
    return { error: "This server isn't in a failed state." };
  }
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.$transaction([
    db.server.update({
      where: { id: server.id },
      data: { status: "PROVISIONING", provisionError: null },
    }),
    db.job.create({ data: { type: "PROVISION", serverId } }),
  ]);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.retry_provision", detail: serverId },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

