/**
 * DEPLOYMENT CONFIRMATION — sent once a server is provisioned and reachable.
 * TRANSACTIONAL: the helper `sendServerDeployedEmail` sends it with the CRITICAL
 * `provision_ready` kind so it always lands. The root password is NEVER included
 * — the customer reads it from the dashboard under "Show password". `sshEndpoint`
 * is "<publicIp>:<port>" for a NAT server or just "<publicIp>" for a dedicated IP.
 */
serverDeployed: (a: {
  hostname: string;
  planName: string;
  sshEndpoint: string;
  dashboardUrl: string;
}): BuiltEmail => {
  // Split "<host>:<port>" (NAT) vs "<host>" (dedicated) into an ssh command.
  const idx = a.sshEndpoint.lastIndexOf(":");
  const host = idx > 0 ? a.sshEndpoint.slice(0, idx) : a.sshEndpoint;
  const port = idx > 0 ? a.sshEndpoint.slice(idx + 1) : "";
  const sshCmd = port ? `ssh root@${host} -p ${port}` : `ssh root@${host}`;
  return build({
    template: "server_deployed",
    subject: `Your Nxeon server ${a.hostname} is ready \u{1F680}`,
    preheader: `${a.hostname} is provisioned and online — connect over SSH in seconds.`,
    eyebrow: "Server ready",
    accent: "success",
    heading: "Your server is ready",
    blocks: [
      emailParagraph(
        `Your <b>${escHtml(a.planName)}</b> server <b>${escHtml(a.hostname)}</b> is provisioned and online. Connect to it over SSH with:`
      ),
      emailPanel(emailCode(sshCmd), "success"),
      emailParagraph(
        `Your root password is in your dashboard under <b>&ldquo;Show password&rdquo;</b> — for your security we never put it in an email.`
      ),
      emailParagraph(
        `Getting started: once you're in, run <code>apt update &amp;&amp; apt upgrade</code> (Debian/Ubuntu) to bring the system up to date, then you're ready to build.`
      ),
    ],
    cta: { href: a.dashboardUrl, label: "Open your server dashboard", accent: "success" },
    note: `Manage power, backups, firewall and more from your <a href="${a.dashboardUrl}" style="color:#6f47f5;">server dashboard</a>.`,
  });
},

