import { db } from "./db";
import { sendMail } from "./mailer";
import { emails } from "./email-templates";
import { appUrl } from "./email-render";

/**
 * Deployment-confirmation email helper.
 *
 * Sends the "your server is ready" email once a server is provisioned and
 * reachable, from BOTH the provision success path (worker) and the admin
 * "reconcile from Proxmox" recovery. It is deliberately:
 *
 *  - TRANSACTIONAL: sent with the CRITICAL `provision_ready` kind so a customer
 *    preference can never suppress it (see lib/prefs.ts).
 *  - DEDUPED via `EmailLog`: `EmailLog` has no `serverId` column and we add no
 *    schema, so the dedupe keys on the template tag + the customer + the
 *    server-unique dashboard path that the rendered HTML always contains. Only
 *    a prior SENT row blocks a resend, so a failed attempt can still be retried
 *    on the next reconcile/provision.
 *  - BEST-EFFORT: it runs on the provision money-path, so it swallows every
 *    error and NEVER throws into the caller.
 */

const DEPLOY_TEMPLATE = "server_deployed";

type DeployedServer = {
  id: string;
  hostname: string;
  sshPort: number | null;
  userId: string;
  plan?: { name?: string | null } | null;
  node?: { publicIp?: string | null } | null;
};

type DeployedUser = { email?: string | null } | null | undefined;

export async function sendServerDeployedEmail(
  server: DeployedServer,
  user: DeployedUser
): Promise<void> {
  try {
    const email = user?.email;
    if (!email) return;

    const dashboardUrl = `${appUrl()}/dashboard/servers/${server.id}`;

    // Per-server dedupe (see file header). The dashboard path is server-unique
    // and survives EmailLog redaction (only secret query params are stripped).
    const already = await db.emailLog.findFirst({
      where: {
        template: DEPLOY_TEMPLATE,
        userId: server.userId,
        status: "SENT",
        html: { contains: `/dashboard/servers/${server.id}` },
      },
      select: { id: true },
    });
    if (already) return;

    // ALWAYS the node's public IP + forwarded ssh port — never the internal
    // 10.20.x.x address, which is unreachable from outside the host.
    const host = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
    const sshEndpoint = server.sshPort ? `${host}:${server.sshPort}` : host;

    const tpl = emails.serverDeployed({
      hostname: server.hostname,
      planName: server.plan?.name ?? "Nxeon",
      sshEndpoint,
      dashboardUrl,
    });

    await sendMail({
      to: email,
      subject: tpl.subject,
      html: tpl.html,
      // Records EmailLog.template = "server_deployed" — the dedupe key above.
      template: tpl.template,
      userId: server.userId,
      // CRITICAL kind → non-suppressible transactional delivery.
      kind: "provision_ready",
    });
  } catch (e) {
    console.error("[server-deployed-email] send failed (non-fatal)", e);
  }
}

