async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any; user: any }> {
  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    // `user` (email) + `node` (publicIp) are needed for the deployment
    // confirmation email fired on provision success; the rest is used throughout.
    include: { plan: true, osTemplate: true, node: true, user: { select: { id: true, email: true } } },
  });

await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });

// Deployment confirmation email (transactional, deduped via EmailLog). Runs on
// the provision money-path, so it is best-effort and must never fail the build.
try {
  const { sendServerDeployedEmail } = await import("../lib/server-deployed-email");
  await sendServerDeployedEmail(server, (server as any).user);
} catch (e) {
  console.error("[worker] deployment-confirmation email failed (non-fatal)", e);
}

